namespace LogicGate.SiteFactory.Application.Generation;

/// <summary>An opaque plan identifier supplied by the caller, never generated by the contract.</summary>
public sealed record GenerationPlanId
{
    public GenerationPlanId(string value)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value);
        Value = value;
    }

    public string Value { get; }

    public override string ToString() => Value;
}
